const D = { energy: .6, scale: 1, speed: 1, density: .55, tau: .5, hue: 24, x: .5, y: .5, style: 'basalt', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Plate tectonics in miniature, on a lava lake ---------------------------
// A COMPRESSIBLE velocity field v = grad(phi) drives a crustal AGE field by
// semi-Lagrangian advection. Where the flow diverges the crust is torn open and
// new skin is born (age 0, incandescent); where it converges the plate founders
// and is consumed (age 0 again, the margin glows). Age then cools to black
// basalt as it is rafted away, so symmetric age bands spread from every ridge —
// which is exactly what a seafloor magnetic-anomaly map looks like.
// Anti-convergence: crust is created and destroyed at matched rates forever, and
// phi drifts on incommensurate frequencies so the plate layout never repeats.
const BW = Math.max(340, Math.min(480, Math.round(width / 2.8))), BH = Math.max(96, Math.round(BW * height / width)), N = BW * BH;
const CW = 45, CH = 26;                      // coarse grid for the (expensive) trig

const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}

if (!S.g) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.age = new Float32Array(N); S.age2 = new Float32Array(N);
  S.glow = new Float32Array(N); S.glow2 = new Float32Array(N);
  S.vx = new Float32Array(CW * CH); S.vy = new Float32Array(CW * CH); S.dv = new Float32Array(CW * CH);
  S.seedUsed = null;
}
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.K = [];                                  // 5 incommensurate plate-driving modes
  for (let m = 0; m < 5; m++) {
    S.K.push({
      kx: (fr(m * 7 + 1) - 0.5) * 6.6, ky: (fr(m * 7 + 2) - 0.5) * 6.6,
      w: (fr(m * 7 + 3) - 0.5) * 0.30, ph: fr(m * 7 + 4) * 6.283,
      a: 0.5 + fr(m * 7 + 5) * 0.7,
    });
  }
  for (let k = 0; k < N; k++) { S.age[k] = hsh(k % BW, (k / BW) | 0) * 0.7; S.glow[k] = 0; }
}

const spd = 0.35 + P.speed * 1.0;
const tt = K.t;
// ---- velocity + divergence, analytic, on the coarse grid -------------------
for (let j = 0; j < CH; j++) for (let i = 0; i < CW; i++) {
  const x = i / CW * 6.0, y = j / CH * 3.4;
  let vx = 0, vy = 0, dv = 0;
  for (let m = 0; m < 5; m++) {
    const M = S.K[m], ang = M.kx * x + M.ky * y + M.w * tt + M.ph;
    const c = Math.cos(ang), s2 = Math.sin(ang);
    vx += M.a * M.kx * c; vy += M.a * M.ky * c;
    dv -= M.a * (M.kx * M.kx + M.ky * M.ky) * s2;      // div(grad phi) = laplacian(phi)
  }
  const k = j * CW + i; S.vx[k] = vx; S.vy[k] = vy; S.dv[k] = dv;
}
// Normalise against the field's OWN statistics. The raw amplitudes depend on the
// seeded wavenumbers, so a fixed threshold either tears every cell (a white-hot
// mush with no plates) or none. Ridges = the top tail of |div|.
let sv = 0, sd2 = 0;
for (let k = 0; k < CW * CH; k++) { sv += S.vx[k] * S.vx[k] + S.vy[k] * S.vy[k]; sd2 += S.dv[k] * S.dv[k]; }
const rmsV = Math.sqrt(sv / (CW * CH)) + 1e-6, rmsD = Math.sqrt(sd2 / (CW * CH)) + 1e-6;
const samp = (F, u, v) => {                  // bilinear on the coarse grid
  let x = u * (CW - 1), y = v * (CH - 1);
  if (x < 0) x = 0; else if (x > CW - 1.001) x = CW - 1.001;
  if (y < 0) y = 0; else if (y > CH - 1.001) y = CH - 1.001;
  const i = x | 0, j = y | 0, fx = x - i, fy = y - j, k = j * CW + i;
  return F[k] * (1 - fx) * (1 - fy) + F[k + 1] * fx * (1 - fy) + F[k + CW] * (1 - fx) * fy + F[k + CW + 1] * fx * fy;
};

// ---- advect the crust ------------------------------------------------------
// Plate speed and age growth BOTH scale with spd, so band width (speed x cooling
// time) stays the same and `speed` reads as tempo, not as a different picture.
const vn2 = 0.22 * spd / rmsV;
const tau = 20 + P.tau * 130;                // cooling time -> how wide the age bands read
const thr = rmsD * (2.3 - P.density * 1.1); // only the top tail of |div| tears the crust
const age = S.age, age2 = S.age2;
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
  const u = i / (BW - 1), v = j / (BH - 1);
  const vx = samp(S.vx, u, v) * vn2, vy = samp(S.vy, u, v) * vn2;
  // Trace back. The wrap MUST land bx in [0,BW) with fx in [0,1): a stray
  // negative weight turns this bilinear interpolation into an extrapolation,
  // which feeds back through the age field and blows up to +/-Infinity.
  let bx = (i - vx) % BW; if (bx < 0) bx += BW;
  let by = j - vy; if (by < 0) by = 0; else if (by > BH - 1) by = BH - 1;
  const ii = bx | 0, i2 = (ii + 1) % BW, fx = bx - ii;
  let jj = by | 0; if (jj > BH - 2) jj = BH - 2;
  const j2 = jj + 1, fy = by - jj;
  const a = age[jj * BW + ii] * (1 - fx) * (1 - fy) + age[jj * BW + i2] * fx * (1 - fy)
          + age[j2 * BW + ii] * (1 - fx) * fy + age[j2 * BW + i2] * fx * fy;
  const dvv = samp(S.dv, u, v);
  let na = a + spd;
  // crust torn open (div>0) or foundered (div<0): either way fresh skin
  if (dvv > thr || dvv < -thr) na = 0;
  if (na > 900) na = 900;
  age2[j * BW + i] = na;
}
S.age = age2; S.age2 = age;

// ---- cheap separable bloom on the hot channel ------------------------------
const AG = S.age, GL = S.glow, G2 = S.glow2;
for (let k = 0; k < N; k++) GL[k] = Math.exp(-AG[k] / (tau * 0.55));
for (let j = 0; j < BH; j++) for (let i = 2; i < BW - 2; i++) {
  const k = j * BW + i;
  G2[k] = (GL[k - 2] + GL[k - 1] * 2 + GL[k] * 3 + GL[k + 1] * 2 + GL[k + 2]) * 0.1111;
}
for (let j = 2; j < BH - 2; j++) for (let i = 0; i < BW; i++) {
  const k = j * BW + i;
  GL[k] = (G2[k - 2 * BW] + G2[k - BW] * 2 + G2[k] * 3 + G2[k + BW] * 2 + G2[k + 2 * BW]) * 0.1111;
}

// ---- render ----------------------------------------------------------------
const st = P.style;
const rot = h => (((h + (P.hue - 24)) % 360) + 360) % 360;
function hsv(h, s, v) {
  h = ((h % 360) + 360) % 360 / 60; const c = v * s, xx = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  let r, g2, b2;
  if (h < 1) { r = c; g2 = xx; b2 = 0; } else if (h < 2) { r = xx; g2 = c; b2 = 0; }
  else if (h < 3) { r = 0; g2 = c; b2 = xx; } else if (h < 4) { r = 0; g2 = xx; b2 = c; }
  else if (h < 5) { r = xx; g2 = 0; b2 = c; } else { r = c; g2 = 0; b2 = xx; }
  return [(r + m) * 255, (g2 + m) * 255, (b2 + m) * 255];
}
const gain = 0.76 + P.energy * 0.5 + K.intensity * 0.14 + A.rms * 0.3;
const puls = 1 + (K.pulse * 0.05 + A.bass * 0.10) * P.energy;   // partial, never a full-frame flash
const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
  const k = j * BW + i;
  const a = S.age[k];
  const T = Math.exp(-a / tau);                 // 1 = fresh skin, 0 = cold basalt
  const bloom = S.glow[k];
  const gr = 0.86 + hsh(i * 3 + 11, j * 3 + 7) * 0.28;   // crust granularity
  let r, g2, b;
  if (st === 'seafloor') {
    // abstracted: magnetic-anomaly age stripes, exactly a seafloor-age plate
    const band = a / 15, f2 = band - Math.floor(band);
    const c = hsv((200 - Math.min(1, a / 200) * 210 + 360) % 360, 0.62 + f2 * 0.20,
                  (0.36 + (1 - Math.min(1, a / 220)) * 0.36 + (f2 < 0.12 ? 0.13 : 0) + bloom * 0.30) * gain);
    r = c[0]; g2 = c[1]; b = c[2];
  } else if (st === 'ironbow') {
    const m = Math.min(1, (T * 1.1 + bloom * 0.5) * puls);
    const c = hsv(rot(250 - m * 250), 0.85 - m * 0.55, (0.16 + m * 0.80) * gain);
    r = c[0]; g2 = c[1]; b = c[2];
  } else if (st === 'ink') {
    const v = 0.80 - Math.min(1, T * 1.2 + bloom * 0.4) * 0.66;
    const c = hsv(rot(30), 0.07, Math.max(0, v) * gr * gain);
    r = c[0]; g2 = c[1]; b = c[2];
  } else {
    // basalt (default): blackbody skin over a warm, textured, never-black rind
    const m = Math.min(1, T * puls);
    let h2, s2, v2;
    if (m > 0.72) { h2 = rot(52) - (m - 0.72) * 20; s2 = 0.20 + (1 - m) * 1.6; v2 = 0.96; }
    else if (m > 0.40) { h2 = rot(30) + (m - 0.40) * 46; s2 = 0.92; v2 = 0.62 + (m - 0.40) * 1.05; }
    else if (m > 0.14) { h2 = rot(12) + (m - 0.14) * 62; s2 = 0.95; v2 = 0.24 + (m - 0.14) * 1.45; }
    else { h2 = rot(18); s2 = 0.30 + m * 3.4; v2 = 0.15 + m * 0.65; }        // rind: warm grey, not black
    const c = hsv(h2, Math.min(1, s2), Math.min(1, (v2 * gr + bloom * 0.42 * (1 - m)) * gain));
    r = c[0]; g2 = c[1]; b = c[2];
  }
  const o = k * 4; px[o] = r; px[o + 1] = g2; px[o + 2] = b; px[o + 3] = 255;
}
g.updatePixels();

const z2 = Math.max(1, P.scale), hw = 0.5 / z2;
const cx = Math.min(1 - hw, Math.max(hw, P.x)), cy = Math.min(1 - hw, Math.max(hw, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, (cx - hw) * BW, (cy - hw) * BH, 2 * hw * BW, 2 * hw * BH);
pop();
blendMode(BLEND); drawingContext.shadowBlur = 0; noTint();
